//! `services::pyyaml` (the PyYAML 6.0.3 port copied from Agent Hub, PORTING.md A-1/A-4) against PyYAML itself:
//! tests/fixtures/pyyaml/yaml_{load,dump,random}.json, generated by parity/gen/gen_yaml_golden.py (inputs: every
//! YAML text/value Nemo's backend test suite loads or dumps, the YAML files under the reference's backend/tests,
//! a scalar/string matrix, a malformed-document corpus and a seeded random batch). Values use the typed JSON encoding of
//! parity/gen/yaml_codec.py.

mod pyyaml_support;

use pyyaml_support::{big_stack, golden, report, run_dumps, run_loads};

#[test]
fn golden_loads_match_pyyaml() {
    big_stack(|| {
        let g = golden("yaml_load.json");
        let mut failures = Vec::new();
        let n = run_loads(g.as_array().map_or(&[][..], Vec::as_slice), &mut failures);
        assert!(n > 2000, "only {n} load cases");
        report("loads", n, &failures);
    });
}

#[test]
fn golden_dumps_match_pyyaml() {
    big_stack(|| {
        let g = golden("yaml_dump.json");
        let mut failures = Vec::new();
        let n = run_dumps(g.as_array().map_or(&[][..], Vec::as_slice), &mut failures);
        assert!(n > 10_000, "only {n} dump checks");
        report("dumps", n, &failures);
    });
}

#[test]
fn golden_random_batch_matches_pyyaml() {
    big_stack(|| {
        let g = golden("yaml_random.json");
        let mut failures = Vec::new();
        let mut n = run_dumps(
            g["dumps"].as_array().map_or(&[][..], Vec::as_slice),
            &mut failures,
        );
        n += run_loads(
            g["loads"].as_array().map_or(&[][..], Vec::as_slice),
            &mut failures,
        );
        assert!(n > 3000, "only {n} random checks");
        report("random batch", n, &failures);
    });
}

/// The entry points Nemo's adapters call: `safe_load_value` (a tree) and `safe_dump` with the option sets they pass;
/// errors carry PyYAML's class, `str(e)`, the real `problem` / `context` attributes and the marks.
#[test]
fn entry_points_are_safe_load_and_safe_dump() {
    use nemo_console::services::pyyaml::{self as yaml, DumpOpts, PyValue};
    let v = yaml::safe_load_value("b: 1\na: [x, 2.5, yes, 0o7, 010, 1:30]\n").unwrap_or_default();
    assert_eq!(
        yaml::safe_dump(&v, &DumpOpts::SAFE_DUMP),
        "a:\n- x\n- 2.5\n- true\n- 0o7\n- 8\n- 90\nb: 1\n"
    );
    assert_eq!(
        yaml::safe_dump(&v, &DumpOpts::SAFE_DUMP_UNSORTED),
        "b: 1\na:\n- x\n- 2.5\n- true\n- 0o7\n- 8\n- 90\n"
    );
    assert_eq!(yaml::safe_load_value("").ok(), Some(PyValue::None));
    let e = yaml::safe_load("a: [").err();
    assert_eq!(e.as_ref().map(yaml::YamlError::class), Some("ParserError"));
    assert_eq!(
        e.as_ref().and_then(|e| e.context()),
        Some("while parsing a flow node")
    );
    let problem = "expected the node content, but found '<stream end>'";
    assert_eq!(e.as_ref().and_then(|e| e.problem()), Some(problem));
    assert_eq!(
        e.as_ref().map(yaml::YamlError::problem_or_str).as_deref(),
        Some(problem)
    );
    assert_eq!(
        e.and_then(|e| e.problem_mark())
            .map(|m| (m.line, m.column, m.index)),
        Some((0, 4, 4))
    );
}
